qtd = int(input("Quantas notas? "))

if qtd <= 0:
    print("É preciso ao menos uma nota.")
else:
    notas = []
    for i in range(qtd):
        nota = float(input(f"Nota {i + 1}: ").replace(",", "."))
        notas.append(nota)

    soma = 0
    maior = notas[0]
    menor = notas[0]
    for nota in notas:
        soma += nota
        if nota > maior:
            maior = nota
        if nota < menor:
            menor = nota
    media = soma / len(notas)

    acima = 0
    for nota in notas:
        if nota > media:
            acima += 1

    print(f"Média: {media:.2f} | Maior: {maior} | Menor: {menor}")
    print(f"Notas acima da média: {acima}")

