sequencia = input("Sequência de DNA: ").strip().upper()

valida = sequencia != ""
for base in sequencia:
    if base not in "ATCG":
        valida = False
        break

if not valida:
    print("Sequência inválida: use apenas A, T, C e G.")
else:
    contagem = {"A": 0, "T": 0, "C": 0, "G": 0}
    for base in sequencia:
        contagem[base] += 1

    gc = (contagem["G"] + contagem["C"]) / len(sequencia) * 100

    complemento = {"A": "T", "T": "A", "C": "G", "G": "C"}
    complementar_reversa = ""
    for base in sequencia:
        complementar_reversa = complemento[base] + complementar_reversa

    for base, qtd in contagem.items():
        print(f"{base}: {qtd}")
    print(f"Conteúdo GC: {gc:.1f}%")
    print(f"Complementar reversa: 5'-{complementar_reversa}-3'")
